results = {str(i): json.loads((ROOT / f'lab_0{i}/results/results.json').read_text(encoding='utf-8')) for i in range(1, 6)}
assets = HERE / 'assets'; assets.mkdir(exist_ok=True)
(assets / 'code').mkdir(exist_ok=True)
(assets / 'notebooks').mkdir(exist_ok=True)
for source in (ROOT / 'project').glob('*.py'):
    shutil.copy2(source, assets / 'code' / source.name)
for i in range(1, 6):
    plots = list((ROOT / f'lab_0{i}').rglob('*.png'))
    # One real source plot per lab, referenced explicitly in each lesson.
    preferred = ['diagnostics', 'client', 'confusion', 'importance', 'learning_curves'][i-1]
    chosen = next((p for p in plots if preferred in p.stem), plots[0])
    dest = assets / f'lab{i}_{chosen.name}'
    shutil.copy2(chosen, dest)
    lessons[i]['figure'] = f'assets/{dest.name}'
    lessons[i]['figureSource'] = str(chosen.relative_to(ROOT)).replace('\\', '/')
    notebook = ROOT / f'lab_0{i}/Практична_{i}_Панчишин.ipynb'
    shutil.copy2(notebook, assets / 'notebooks' / notebook.name)
    lessons[i]['source'] = f'assets/code/lab0{i}.py'
    lessons[i]['notebook'] = f'assets/notebooks/{notebook.name}'

payload = dict(lessons=lessons, results=results)
(HERE / 'content.js').write_text('window.COURSE = '+json.dumps(payload, ensure_ascii=False)+';\n', encoding='utf-8')
print('Built', len(lessons), 'lessons;', sum(len(x['quiz']) for x in lessons), 'questions; real results for five labs.')
